package handlers
// CancelOrder handles seller cancellation.
func CancelOrder(order Order, bus Bus) error {
    return bus.Publish("OrderCancelled", OrderCancelled{OrderID: order.ID, BuyerID: order.BuyerID, Reason: "seller_cancelled"})
}

package consumers
// Subscribed to OrderCancelled.
func OnOrderCancelled(event OrderCancelled, mail Mailer) error {
    if event.Reason != "payment_expired" { return nil }
    return mail.Send(event.BuyerID, "order_cancelled", event.OrderID)
}

package handlers

// Synthetic fragment: подтверждение доставки отправления.
func MarkDelivered(shipment Shipment, bus Bus) error {
    return bus.Publish("ShipmentDelivered", ShipmentDelivered{
        ShipmentID: shipment.ID,
        OrderID: shipment.OrderID,
        DeliveredAt: shipment.DeliveredAt,
    })
}

package consumers

// Synthetic fragment. Subscription: ShipmentDelivered.
func OnShipmentDelivered(event ShipmentDelivered, orders Store) error {
    // Current defect: records time but leaves status as shipped.
    return orders.SetDeliveredAt(event.OrderID, event.DeliveredAt)
}
